(() => {
  'use strict';
  const $ = document.getElementById('app');
  const view = document.body.dataset.view;
  const q = new URLSearchParams(location.search);
  const chamber = q.get('chamber') === 'senate' ? 'senate' : 'house';
  const district = Math.min(75, Math.max(1, Number(q.get('district')) || 33));
  const id = q.get('id') || 'house-33-rep-primary-jessica-drew-day';
  const base = '../../data/';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const norm = value => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\b(jr|sr|ii|iii|iv)\b/g,'').replace(/\s+/g,' ').trim();
  const firstLast = value => { const tokens=norm(value).split(' ');return [tokens[0],tokens.at(-1)].join(' '); };
  const money = value => Number.isFinite(Number(value)) ? new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value) : '—';
  const number = value => Number.isFinite(Number(value)) ? new Intl.NumberFormat('en-US').format(value) : '—';
  const party = value => /^DEM/i.test(value) ? 'Democrat' : /^REP/i.test(value) ? 'Republican' : 'Independent';
  const partyClass = value => /^REP/i.test(value) ? 'rep' : /^DEM/i.test(value) ? '' : 'ind';
  const office = ch => ch === 'house' ? 'State House' : 'State Senate';
  const raceUrl = (ch,d) => `race.html?chamber=${encodeURIComponent(ch)}&district=${d}`;
  const profileUrl = candidate => `candidate.html?id=${encodeURIComponent(candidate.candidate_id)}`;
  const financeUrl = candidate => `finance.html?id=${encodeURIComponent(candidate.candidate_id)}`;
  const source = (url,label='Source') => url && /^https?:\/\//.test(url) ? `<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>` : '';
  const initials = name => name.split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase();
  const photo = (candidate,large=false) => `<div class="portrait-wrap"><div class="avatar ${large?'large':''}" role="img" aria-label="Portrait placeholder for ${esc(candidate.name)}">${esc(initials(candidate.name))}</div>${large?'<span class="avatar-note">Verified photo pending</span>':''}</div>`;
  const genericPlaceholder = (title,body) => `<div class="placeholder"><strong>${esc(title)}</strong>${esc(body)}</div>`;
  const panel = (title,content,note='',anchor='') => `<section class="panel anchor" ${anchor?`id="${esc(anchor)}"`:''}><div class="panel-head"><h2>${esc(title)}</h2></div>${content}${note?`<p class="section-note">${esc(note)}</p>`:''}</section>`;
  const nav = (ch,d,candidate) => {
    const tabs=[['race',raceUrl(ch,d),'Race & opponents'],['candidate',candidate?profileUrl(candidate):'#','Candidate profile'],['finance',candidate?financeUrl(candidate):'#','Campaign finance']];
    return `<div class="site-header"><div class="shell header-row"><a class="brand" href="../../index.html"><span class="brand-mark">RI</span>Rhode Island Elections Project</a><span class="prototype-tag">Local design prototype</span></div></div><div class="shell"><div class="breadcrumb"><a href="../../index.html">RIEP</a> / ${esc(office(ch))} District ${d}${candidate?' / '+esc(candidate.name):''}</div><nav class="tabs" aria-label="Candidate page sections">${tabs.map(([key,href,label])=>`<a href="${esc(href)}" ${key===view?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav></div>`;
  };
  const footer = () => `<footer class="footer"><div class="shell">Prototype for review only. Figures retain their source periods; absent data is labeled. These pages are not linked from the live site.</div></footer>`;
  const load = async path => {const response=await fetch(base+path,{cache:'no-store'});if(!response.ok)throw new Error(`${path}: ${response.status}`);return response.json();};
  Promise.all([
    load('whos_running_2026.json'),load('candidate_research_2026_with_endorsements.json'),
    load('candidate_profiles_2026.json'),load('candidate_finance_2026.json'),
    load('outside_ratings_2026.json'),load('race_data.json'),
    load('ri_turnout_2024_precinct.geojson'),load('house_legislative_progress_2025_2026.json')
  ]).then(([roster,research,profiles,finance,ratings,history,turnout,houseProgress])=>{
    const active = (ch,d) => {
      const rec=roster.chambers?.[ch]?.[String(d)] || {};
      const seen=new Set();
      return [...(rec.candidates||[]),...(rec.general_candidates||[])].filter(c=>{
        if(seen.has(c.candidate_id))return false;seen.add(c.candidate_id);
        return c.election_status==='general_candidate'||c.on_election_ballot===true;
      }).map(c=>({...c,chamber:ch,district_number:Number(d)}));
    };
    const allCandidates=Object.entries(roster.chambers).flatMap(([ch,ds])=>Object.values(ds).flatMap(rec=>active(ch,rec.district_number)));
    const candidate=(view==='race' ? active(chamber,district)[0] : allCandidates.find(c=>c.candidate_id===id)) || active(chamber,district)[0];
    if(!candidate)throw new Error('No candidate in the selected district.');
    const ch=candidate.candidate_id.split('-')[0],d=candidate.district_number;
    const researchFor=c => research.candidates.find(r=>r.candidate_id===c.candidate_id) || research.candidates.find(r=>r.chamber===ch&&Number(r.district_number)===Number(d)&&firstLast(r.candidate_name)===firstLast(c.name)) || {};
    const profileFor=c => profiles.profiles.find(p=>p.candidate_id===c.candidate_id) || {};
    const financeFor=c => finance.profiles.find(p=>p.chamber===ch&&Number(p.district_number)===Number(d)&&firstLast(p.candidate_name)===firstLast(c.name));
    const ratingsFor=c => ratings.ratings.filter(r=>r.chamber===ch&&Number(r.district_number)===Number(d)&&firstLast(r.candidate_name)===firstLast(c.name));
    const turnoutFor=c => turnout.features.find(f=>String(f.properties?.DISTRICT||'')===String(c.home_precinct_code||''));
    const prioritiesFor=c => profileFor(c).priorities?.length ? profileFor(c).priorities : researchFor(c).priorities || [];
    const endorsementsFor=c => {const seen=new Set();return (researchFor(c).endorsements||[]).filter(e=>{const name=e.organization||e.name;if(!name||seen.has(norm(name)))return false;seen.add(norm(name));return true;});};
    const electoralHistory=c=>Object.values(history).filter(r=>String(r.chamber).toLowerCase()===ch&&Number(r.district_number)===Number(d)).sort((a,b)=>b.year-a.year).map(r=>({race:r,candidate:(r.candidates||[]).find(x=>firstLast(x.name)===firstLast(c.name))}));
    const card = c => {const priorities=prioritiesFor(c),f=financeFor(c);return `<article class="candidate-tile"><div class="identity">${photo(c)}<div><span class="pill ${partyClass(c.party)}">${party(c.party)}</span><h2>${esc(c.name)}</h2><small>${esc(c.status_label||'2026 candidate')}</small></div></div><p class="tile-facts">${esc(c.hometown||'Rhode Island')} · ${esc(office(ch))} District ${d}<br><strong>${priorities.length?'Published priorities available':'Priorities not documented'}</strong>${f?' · Finance report available':''}</p><div class="tile-actions"><a class="btn primary" href="${profileUrl(c)}">View candidate profile</a><a class="btn" href="${financeUrl(c)}">Finance</a></div></article>`;};
    const historyPanel = c => {const rows=electoralHistory(c);return panel('Past electoral performance',rows.length?`<div>${rows.map(({race,candidate:result})=>`<div class="history-row"><span><strong>${race.year} general · District ${d}</strong><small>${result?`${number(String(result.votes).replace(/,/g,''))} votes · ${result.pct||'vote share unavailable'}`:'No candidate result in this race record'}</small></span><b>${result?esc(result.role||'Candidate'):'—'}</b></div>`).join('')}</div>`:genericPlaceholder('No matching result','The project does not yet have a matched historical result for this candidate.'),'District-level general-election results; primary performance will appear when matched candidate-level data is available.','performance');};
    const precinctPanel = c => {const t=turnoutFor(c)?.properties;return panel('Home precinct context',t?`<div class="metric-row"><div class="metric"><b>${esc(c.home_precinct_code)}</b><span>${esc(t.TOWN)} precinct</span></div><div class="metric"><b>${number(t.VOTED)}</b><span>Voted in 2024 general</span></div><div class="metric"><b>${Number(t.PCTVOTEDGEN).toFixed(1)}%</b><span>2024 turnout of eligible voters</span></div></div>`:genericPlaceholder('Precinct data pending','No matched 2024 precinct turnout record is available.'),'This is turnout in the candidate’s public filing home precinct, not the candidate’s vote share.');};
    const prioritiesPanel=c=>{const items=prioritiesFor(c);return panel('Campaign priorities',items.length?`<ul class="list">${items.slice(0,5).map(p=>`<li><strong>${esc(p.title)}</strong><span>${esc(p.summary)}</span> ${source(p.source_url,p.source_label||'Campaign source')}</li>`).join('')}</ul>`:genericPlaceholder('No verified priorities yet','Positions will appear only when supported by a candidate response or a cited source.'),'Positions are attributed to the candidate or named source; no party-based positions are inferred.','priorities');};
    const endorsementsPanel=c=>{const items=endorsementsFor(c);return panel('Endorsements',items.length?`<ul class="list">${items.map(e=>`<li><strong>${esc(e.organization||e.name)}</strong>${source(e.source_url,'Verify endorsement')}</li>`).join('')}</ul>`:genericPlaceholder('No verified endorsements','The current research data has no sourced endorsements for this candidate.'),'Listed organizations are independent of RIEP.','endorsements');};
    const ratingPanels=c=>{const items=ratingsFor(c);return panel('Outside scorecards & Lawmakers score',items.length?items.map(r=>`<div class="score-row"><span><strong>${esc(r.organization)}</strong><small>${esc(r.year||'Year not listed')} · ${esc(r.source_type||'Outside rating')}</small>${source(r.source_url,'Source and methodology')}</span><b>${esc(r.rating||'—')}</b></div>`).join(''):genericPlaceholder('No matched scorecards','No outside rating or Lawmakers score is linked to this candidate in current project data.'),'Each measure belongs to its publishing organization. A historical Lawmakers score is labeled by its session; it is not a 2025–2026 score.','scores');};
    const legislationPanel=c=>{const rec=ch==='house'?houseProgress.records.find(r=>Number(r.district_number)===Number(d)&&firstLast(r.candidate_name)===firstLast(c.name)):null;return panel('Legislative record',rec?`<div class="metric-row"><div class="metric"><b>${number(rec.legislation.prime_sponsored)}</b><span>Prime-sponsored bills</span></div><div class="metric"><b>${number(rec.legislation.passed_chamber)}</b><span>Passed House</span></div><div class="metric"><b>${number(rec.legislation.became_law)}</b><span>Became law</span></div></div>`:genericPlaceholder('Record not in this data set','This prototype has a 2025–2026 House bill-progress data set. Other records require a verified source.'),ch==='house'?'2025–2026 House bill progress; excludes resolutions. This is not a Lawmakers effectiveness score.':'Legislative activity can be connected when a verified Senate data set is available.','record');};
    const financeSummary=c=>{const f=financeFor(c);return panel('Campaign finance snapshot',f?`<div class="metric-row"><div class="metric"><b>${money(f.money_raised)}</b><span>Raised</span></div><div class="metric"><b>${money(f.money_spent)}</b><span>Spent</span></div><div class="metric"><b>${money(f.ending_cash)}</b><span>Cash on hand</span></div></div><p class="section-note">${esc(f.report_label||'Latest linked report')} · ${esc(f.reporting_period_label||'Period not listed')}</p><p><a class="btn" href="${financeUrl(c)}">Explore finance report</a></p>`:genericPlaceholder('Finance profile pending','No candidate finance profile is matched in the current data.'),'Figures reflect the linked filing period, not a live balance.','finance');};
    const socialPanel=()=>panel('Digital conversation',genericPlaceholder('Research module planned','A future listening view could summarize public posts by topic and date, with source links and methodology. No sentiment or audience claims are displayed without collected data.'),'Design placeholder only; no social media monitoring is active.','social');
    if(view==='race'){
      const cs=active(ch,d),prev=Object.values(history).filter(r=>String(r.chamber).toLowerCase()===ch&&Number(r.district_number)===Number(d)).sort((a,b)=>b.year-a.year)[0];
      $.innerHTML=nav(ch,d,cs[0])+`<main class="shell"><div class="hero"><div><div class="eyebrow">2026 election · race view</div><h1>${esc(office(ch))} District ${d}</h1><p>Compare candidates in this district, then open an individual profile or a separate finance report. No map scrolling is needed.</p></div><div class="hero-actions"><a class="btn" href="../../running.html?chamber=${ch}&district=${d}">Existing race workspace</a></div></div><div class="grid"><div class="stack">${panel('Candidates in this race',`<div class="candidate-list">${cs.map(card).join('')}</div>`,cs.length===1?'The candidate is currently listed as unopposed in the general election.':'Candidates are shown side by side without an editorial ranking.')} ${panel('District election context',prev?`<div class="metric-row"><div class="metric"><b>${prev.year}</b><span>Most recent general race</span></div><div class="metric"><b>${esc(prev.margin_pct||'—')}</b><span>District margin</span></div><div class="metric"><b>${number(String(prev.district_total_votes||'').replace(/,/g,''))}</b><span>Total votes</span></div></div>`:genericPlaceholder('Historical results pending','No district-level historical race is matched.'),'These are district totals, not precinct candidate performance.')}</div><aside class="stack">${panel('How to use these pages',`<ul class="list"><li><strong>Race</strong><span>Opponents and district context together.</span></li><li><strong>Profile</strong><span>One candidate’s issues, record, and sourced assessments.</span></li><li><strong>Finance</strong><span>Filings and money flows on their own page.</span></li></ul>`)}${panel('Data notes',`<p>Some candidates lack a photo, published priorities, finance details, or a legislative record. Those sections remain clearly labeled until verified data is available.</p>`)}</aside></div></main>`+footer();
    } else if(view==='candidate'){
      const r=researchFor(candidate),campaign=profileFor(candidate).campaign_url||r.campaign_website;
      $.innerHTML=nav(ch,d,candidate)+`<main class="shell"><div class="hero profile-hero">${photo(candidate,true)}<div><div class="eyebrow">Individual candidate profile · ${esc(office(ch))} District ${d}</div><h1>${esc(candidate.name)}</h1><p>${esc(party(candidate.party))} · ${esc(candidate.hometown||'Rhode Island')} · ${esc(candidate.status_label||'2026 candidate')}</p><div class="actions" style="margin-top:18px"><a class="btn primary" href="${raceUrl(ch,d)}">View race & opponents</a><a class="btn" href="${financeUrl(candidate)}">Campaign finance</a>${campaign?`<a class="btn" href="${esc(campaign)}" target="_blank" rel="noopener noreferrer">Campaign website ↗</a>`:''}</div></div></div><div class="grid"><div class="stack">${prioritiesPanel(candidate)}${historyPanel(candidate)}${legislationPanel(candidate)}${endorsementsPanel(candidate)}${ratingPanels(candidate)}</div><aside class="stack">${precinctPanel(candidate)}${financeSummary(candidate)}${socialPanel()}</aside></div></main>`+footer();
    } else {
      const f=financeFor(candidate),period=f?.reporting_period_label||'No matched filing';
      const raised=Number(f?.money_raised)||0,spent=Number(f?.money_spent)||0,total=raised+spent||1;
      $.innerHTML=nav(ch,d,candidate)+`<main class="shell"><div class="hero"><div><div class="eyebrow">2026 campaign finance · ${esc(office(ch))} District ${d}</div><h1>${esc(candidate.name)}</h1><p>Filing figures, reporting period, and source documents in a dedicated finance view.</p></div><div class="hero-actions"><a class="btn" href="${profileUrl(candidate)}">Candidate profile</a><a class="btn" href="${raceUrl(ch,d)}">Race & opponents</a></div></div><div class="stack">${f?`<section class="panel"><div class="panel-head"><h2>Campaign at a glance</h2><small>${esc(f.report_label||'Filing')}</small></div><div class="amounts"><div class="amount"><small>Raised in reporting period</small><strong>${money(raised)}</strong></div><div class="amount"><small>Spent in reporting period</small><strong>${money(spent)}</strong></div><div class="amount"><small>Ending cash on hand</small><strong>${money(f.ending_cash)}</strong></div></div><p class="section-note">${esc(period)}. Raised and spent are period flows; cash on hand is the closing balance.</p></section><div class="grid"><div class="stack">${panel('Filing history',f.filing_history?.length?f.filing_history.map(x=>`<div class="history-row"><span><strong>${esc(x.label)}</strong><small>${esc(x.reporting_period_label||'')}</small></span><b>${money(x.ending_cash)}<small>Ending cash</small></b></div>`).join(''):genericPlaceholder('No prior filing details','Only the summary is available.'))}${panel('Money sources',f.source_buckets?.length?`<div class="finance-bar" aria-label="Illustrative share of raised and spent"><span style="width:${100*raised/total}%"></span><span style="width:${100*spent/total}%"></span></div><ul class="list" style="margin-top:18px">${f.source_buckets.map(x=>`<li><strong>${esc(x.label)} · ${money(x.amount)}</strong><span>${esc(x.description||'')}</span></li>`).join('')}</ul>`:genericPlaceholder('Source breakdown pending','No detailed source categories are available for this filing.'),'Source categories reflect the published filing labels and may not sum to the same period total. Donor names are not inferred.')}</div><aside class="stack">${panel('Original documents',f.original_documents?.length?`<ul class="list">${f.original_documents.map(doc=>`<li><strong>${esc(doc.label)}</strong><span>${esc(doc.period||'')}</span><a class="source-link" href="../..${esc(doc.href)}" target="_blank" rel="noopener">Open filing ↗</a></li>`).join('')}</ul>`:genericPlaceholder('Documents pending','No original filing PDF is linked.'),'Review the original filing for exact amounts and definitions.')}${panel('Scope & source',`<p>${esc(f.source_note||'Derived from Rhode Island campaign finance reports.')}</p><p>${esc(f.coverage_note||'Coverage varies by candidate.')}</p><a class="btn" href="../../finance.html?slug=${encodeURIComponent(f.slug)}">Open existing detailed finance page</a>`)}</aside></div>`:panel('Finance data not matched',genericPlaceholder('No filing profile available','The candidate may have a different filing identifier or may not be in the current finance data. No figures are estimated.'))}</div></main>`+footer();
    }
    document.title=`${candidate.name} · ${view==='race'?'Race':view==='finance'?'Finance':'Candidate profile'} prototype | RIEP`;
  }).catch(error=>{console.error(error);$.innerHTML=`<main class="shell" style="padding-top:50px">${panel('Prototype could not load',genericPlaceholder('Serve from the repository root','Start a local HTTP server and open /prototypes/candidate-pages/race.html. Browser file:// access blocks data requests.'),'Error: '+error.message)}</main>`;});
})();
